import 'package:flutter/material.dart';
import 'package:stacked/stacked.dart';
import '../../../app/app.locator.dart';
import '../../../models/inventory_item.dart';
import '../../../services/inventory_service.dart';
class StockOperationsView extends StackedView<StockOperationsViewModel> {
 const StockOperationsView({super.key});
 @override StockOperationsViewModel viewModelBuilder(BuildContext context)=>StockOperationsViewModel(locator<InventoryService>())..load();
 @override Widget builder(BuildContext context,StockOperationsViewModel vm,Widget? child)=>DefaultTabController(length:3,child:Scaffold(appBar:AppBar(title:const Text('Stock operations'),bottom:const TabBar(tabs:[Tab(text:'Purchases'),Tab(text:'Suppliers'),Tab(text:'Recipes')])),body:vm.isBusy&&!vm.loaded?const Center(child:CircularProgressIndicator()):TabBarView(children:[_Purchases(vm),_Suppliers(vm),_Recipes(vm)])));
}
class StockOperationsViewModel extends BaseViewModel {
 StockOperationsViewModel(this.api); final InventoryService api; bool loaded=false; String branchId=''; String? error;
 List<RestaurantBranch> branches=[]; List<InventoryItem> items=[]; List<Map<String,dynamic>> suppliers=[]; List<Map<String,dynamic>> purchases=[]; List<Map<String,dynamic>> recipes=[];
 Future<void> load() async {setBusy(true);error=null;try{final r=await Future.wait([api.branches(),api.items(),api.suppliers(),api.purchases(),api.recipes()]);branches=r[0] as List<RestaurantBranch>;items=r[1] as List<InventoryItem>;suppliers=r[2] as List<Map<String,dynamic>>;purchases=r[3] as List<Map<String,dynamic>>;recipes=r[4] as List<Map<String,dynamic>>;if(branches.isNotEmpty&&!branches.any((b)=>b.id==branchId))branchId=branches.first.id;loaded=true;}catch(e){error=e.toString();}finally{setBusy(false);notifyListeners();}}
 Future<void> run(Future<void> Function() action) async {setBusy(true);error=null;try{await action();await load();}catch(e){error=e.toString();}finally{setBusy(false);notifyListeners();}}
}
class _Purchases extends StatelessWidget {const _Purchases(this.vm);final StockOperationsViewModel vm;
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[if(vm.error!=null)Text(vm.error!),DropdownButtonFormField<String>(value:vm.branchId.isEmpty?null:vm.branchId,decoration:const InputDecoration(labelText:'Branch'),items:vm.branches.map((b)=>DropdownMenuItem(value:b.id,child:Text(b.name))).toList(),onChanged:(v){if(v!=null){vm.branchId=v;vm.notifyListeners();}}),const SizedBox(height:12),FilledButton.icon(onPressed:vm.items.isEmpty||vm.branchId.isEmpty?null:()=>_newPurchase(context),icon:const Icon(Icons.add),label:const Text('Create purchase')),const SizedBox(height:12),if(vm.purchases.isEmpty)const Text('No purchase drafts yet.'),...vm.purchases.map((p){final id='${p['id']}';final status='${p['status']}';return Card(child:ListTile(title:Text('${p['purchaseNumber']??'Purchase #$id'}'),subtitle:Text('Status: $status • PKR ${p['totalCost']??'0'}'),trailing:status=='draft'?TextButton(onPressed:()=>vm.run(()=>vm.api.receivePurchase(id)),child:const Text('Receive')):const Icon(Icons.check_circle)));})]);
 Future<void> _newPurchase(BuildContext context) async {String? supplier=vm.suppliers.isEmpty?null:'${vm.suppliers.first['id']}';String? item=vm.items.first.id;final qty=TextEditingController(text:'1'),cost=TextEditingController(text:'0');await showDialog<void>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:const Text('Purchase draft'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(value:supplier,decoration:const InputDecoration(labelText:'Supplier'),items:vm.suppliers.map((s)=>DropdownMenuItem(value:'${s['id']}',child:Text('${s['name']}'))).toList(),onChanged:(v)=>set(()=>supplier=v)),DropdownButtonFormField<String>(value:item,decoration:const InputDecoration(labelText:'Inventory item'),items:vm.items.map((i)=>DropdownMenuItem(value:i.id,child:Text(i.name))).toList(),onChanged:(v)=>set(()=>item=v)),TextField(controller:qty,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Quantity')),TextField(controller:cost,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Unit cost (PKR)'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:(){final q=double.tryParse(qty.text),c=double.tryParse(cost.text);if(item==null||q==null||q<=0||c==null||c<0)return;Navigator.pop(ctx);vm.run(()=>vm.api.createPurchase(branchId:vm.branchId,supplierId:supplier,items:[{'inventoryItemId':int.parse(item!), 'quantity':q,'unitCost':c}]));},child:const Text('Save'))])));qty.dispose();cost.dispose();}
}
class _Suppliers extends StatelessWidget {const _Suppliers(this.vm);final StockOperationsViewModel vm;
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[if(vm.error!=null)Text(vm.error!),FilledButton.icon(onPressed:()=>_newSupplier(context),icon:const Icon(Icons.person_add),label:const Text('Add supplier')),const SizedBox(height:12),if(vm.suppliers.isEmpty)const Text('No suppliers yet.'),...vm.suppliers.map((s)=>Card(child:ListTile(leading:const Icon(Icons.local_shipping),title:Text('${s['name']}'),subtitle:Text('${s['phone']??'No phone'}'))))]);
 Future<void> _newSupplier(BuildContext context) async {final name=TextEditingController(),phone=TextEditingController(),notes=TextEditingController();await showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Add supplier'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Name')),TextField(controller:phone,decoration:const InputDecoration(labelText:'Phone')),TextField(controller:notes,decoration:const InputDecoration(labelText:'Notes'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:(){if(name.text.trim().isEmpty)return;Navigator.pop(ctx);vm.run(()=>vm.api.createSupplier(name:name.text.trim(),phone:phone.text.trim(),notes:notes.text.trim()));},child:const Text('Save'))]));name.dispose();phone.dispose();notes.dispose();}
}
class _Recipes extends StatelessWidget {const _Recipes(this.vm);final StockOperationsViewModel vm;
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[if(vm.error!=null)Text(vm.error!),const Text('Link a menu variant ID to the ingredients consumed for its recipe yield.'),const SizedBox(height:12),FilledButton.icon(onPressed:vm.items.where((i)=>i.itemType=='ingredient').isEmpty?null:()=>_newRecipe(context),icon:const Icon(Icons.receipt_long),label:const Text('Create / update recipe')),const SizedBox(height:12),if(vm.recipes.isEmpty)const Text('No recipes configured.'),...vm.recipes.map((r)=>Card(child:ListTile(title:Text('Variant #${r['productVariantId']}'),subtitle:Text('Yield: ${r['yieldQuantity']} • Ingredients: ${(r['items'] as List? ?? []).length}'))))]);
 Future<void> _newRecipe(BuildContext context) async {final variant=TextEditingController(),yieldQty=TextEditingController(text:'1'),qty=TextEditingController(text:'1');final ingredients=vm.items.where((i)=>i.itemType=='ingredient').toList();String? item=ingredients.first.id;await showDialog<void>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:const Text('Recipe builder'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:variant,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Menu variant ID')),TextField(controller:yieldQty,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Yield quantity')),DropdownButtonFormField<String>(value:item,decoration:const InputDecoration(labelText:'Ingredient'),items:ingredients.map((i)=>DropdownMenuItem(value:i.id,child:Text('${i.name} (${i.unit})'))).toList(),onChanged:(v)=>set(()=>item=v)),TextField(controller:qty,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Ingredient quantity'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:(){final v=int.tryParse(variant.text),y=double.tryParse(yieldQty.text),q=double.tryParse(qty.text);if(v==null||v<1||y==null||y<=0||q==null||q<=0||item==null)return;Navigator.pop(ctx);vm.run(()=>vm.api.saveRecipe(variantId:'$v',yieldQuantity:y,items:[{'inventoryItemId':int.parse(item!), 'quantity':q}]));},child:const Text('Save recipe'))])));variant.dispose();yieldQty.dispose();qty.dispose();}
}